const update = $input.first().json;
const sd = $getWorkflowStaticData('global');

if (update.callback_query) {
  const cb = update.callback_query;
  const data = String(cb.data || '');
  const chatId = cb.message?.chat?.id;

  if (data.startsWith('v|')) {
    const parts = data.split('|');
    const account = parts[1] || '';
    const code = parts[2] || '';
    const STATUS = {
      ca: 'Call Again', na: 'No Answer 1-5', n5: 'No Answer 5 UP', rc: 'Recall',
      ni: 'No Interest', np: 'No Potential', wn: 'Wrong Number or Email',
      dr: 'Denied Registration', keep: 'Keep CRM'
    };
    const status = STATUS[code] || code;
    if (!Array.isArray(sd.humanVotes)) sd.humanVotes = [];
    sd.humanVotes.push({ account, status, code, chat_id: chatId, at: new Date().toISOString() });
    if (sd.humanVotes.length > 200) sd.humanVotes = sd.humanVotes.slice(-200);
    return [{ json: {
      route: 'vote', callback_id: cb.id, callback_data: data, chat_id: chatId,
      account, status, code, vote_ack: `Saved: ${account} → ${status}`
    }}];
  }

  if (data === 'rules_chat') {
    sd.mode = 'rules';
    sd.chatHistory = [];
    return [{ json: { route: 'rules_enter', callback_id: cb.id, callback_data: data, chat_id: chatId } }];
  }

  if (data === 'rules_exit') {
    sd.mode = '';
    sd.chatHistory = [];
    sd.pendingProposal = null;
    return [{ json: { route: 'rules_exit', callback_id: cb.id, callback_data: data, chat_id: chatId } }];
  }

  if (data === 'database_check') sd.mode = '';
  return [{ json: {
    route: 'callback', callback_id: cb.id, callback_data: data, chat_id: chatId,
    user_id: String(cb.from?.id || '')
  }}];
}

const message = update.message || {};
const chatId = message.chat?.id;
const text = String(message.text || '').trim();
const low = text.toLowerCase();

if (text.startsWith('/start') || low === 'menu' || low === '/menu') {
  sd.mode = '';
  return [{ json: { route: 'start', chat_id: chatId } }];
}

if (message.document) {
  return [{ json: {
    route: 'document', chat_id: chatId,
    file_id: message.document.file_id,
    file_name: message.document.file_name || 'upload.xlsx',
    mime_type: message.document.mime_type || ''
  }}];
}

// Text menu aliases (if buttons still missing)
if (low === '1' || low === 'database' || low === 'database check' || low === 'db' || low === 'check') {
  sd.mode = '';
  return [{ json: { route: 'callback', callback_id: '', callback_data: 'database_check', chat_id: chatId, from_text: true } }];
}
if (low === '2' || low === 'rules' || low === 'rules brain' || low === 'brain' || low === 'kural') {
  sd.mode = 'rules';
  sd.chatHistory = [];
  return [{ json: { route: 'rules_enter', callback_id: '', callback_data: 'rules_chat', chat_id: chatId, from_text: true } }];
}

if (/^\/(exit|done|menu)$/i.test(text) || /^exit$/i.test(text)) {
  sd.mode = '';
  sd.chatHistory = [];
  sd.pendingProposal = null;
  return [{ json: { route: 'rules_exit', chat_id: chatId, text } }];
}

if (sd.mode === 'rules' && text) {
  return [{ json: { route: 'rules_msg', chat_id: chatId, text, is_confirm: /^confirm$/i.test(text) } }];
}

return [{ json: { route: 'other', chat_id: chatId, text } }];

const route = $('Route Update').item.json;
const item = $input.first();
const binary = item.binary || {};
const key = Object.keys(binary)[0];
if (!key) throw new Error('Telegram download returned no binary');
const b = binary[key];
// ensure filename present for V2 kind detection
if (!b.fileName) b.fileName = route.file_name || 'upload.xlsx';
if (!b.mimeType && route.mime_type) b.mimeType = route.mime_type;
return [{
  json: {
    chat_id: route.chat_id,
    file_name: b.fileName
  },
  binary: { file: b }
}];

const r = $input.first().json;
const sd = $getWorkflowStaticData('global');
sd._rulesMsg = { chat_id: r.chat_id, text: r.text, is_confirm: !!r.is_confirm };
return [{ json: { ...r, _seed: true } }];

const sd = $getWorkflowStaticData('global');
const seed = sd._rulesMsg || $('Route Update').item.json;
const rows = $input.all().map(i => i.json).filter(j => j && !j._seed && (j.trigger_phrase || j.Trigger || j['account no'] === undefined));
const usable = $input.all().map(i => i.json).filter(j => j && (j.trigger_phrase || j.Trigger));
if (!usable.length) {
  return [{ json: { chat_id: seed.chat_id, text: seed.text, is_confirm: seed.is_confirm, trigger_phrase: '', _no_sheet: true } }];
}
return usable.map(j => ({ json: { ...j, chat_id: seed.chat_id, text: seed.text, is_confirm: seed.is_confirm } }));

const sd = $getWorkflowStaticData('global');
const route = sd._rulesMsg || $('Route Update').item.json;
const chatId = route.chat_id;
const userText = String(route.text || '').trim();
const isConfirm = !!route.is_confirm;

function fold(text) {
  return String(text || '')
    .toLowerCase()
    .replace(/ı/g, 'i').replace(/ş/g, 's').replace(/ğ/g, 'g')
    .replace(/ç/g, 'c').replace(/ö/g, 'o').replace(/ü/g, 'u')
    .replace(/[''`"]/g, '')
    .replace(/[;,.\|]+/g, ' ')
    .replace(/\s+/g, ' ')
    .trim();
}

const sheetRows = $input.all().map(i => i.json).filter(j => j && (j.trigger_phrase || j.Trigger));
const active = sheetRows.filter(j => String(j.active ?? j.Active ?? 'true').toLowerCase() !== 'false');

function rowMeta(j, idx) {
  return {
    row: j.row_number ?? j.rowNumber ?? j.__rowNum__ ?? j.row ?? (idx + 2),
    trigger: String(j.trigger_phrase || j.Trigger || '').trim(),
    status: String(j.suggested_status || j.Suggested || j.first_status || '').trim(),
    group: String(j.keyword_group || j.group || '').trim() || 'other',
    repeat: String(j.repeat_logic || '').trim(),
    first: String(j.first_status || '').trim(),
    again: String(j.repeat_status || '').trim(),
    approved: String(j.human_approved || j.reviewed || j.approved || '').trim(),
    source: String(j.source || j.origin || j.created_by || '').trim(),
    active: String(j.active ?? j.Active ?? 'true').trim(),
    when: String(j.when_to_use || '').trim(),
    whenNot: String(j.when_not_to_use || '').trim(),
    intent: String(j.intent || '').trim(),
  };
}

const allMeta = sheetRows.map((j, i) => rowMeta(j, i));
const activeMeta = active.map((j, i) => rowMeta(j, i));

function formatHit(h, i) {
  let s = `${i + 1}) Row ${h.row} [${h.group}]\n   "${h.trigger}" → ${h.status || '?'}`;
  if (h.repeat) s += `\n   repeat: ${h.repeat}` + (h.first || h.again ? ` (${h.first || '?'} → ${h.again || '?'})` : '');
  if (h.source) s += `\n   source: ${h.source}`;
  if (h.approved) s += `\n   approved: ${h.approved}`;
  if (String(h.active).toLowerCase() === 'false') s += `\n   ACTIVE: false`;
  return s;
}

function formatDetail(h) {
  return (
`Sheet row ${h.row}
group: ${h.group}
trigger: "${h.trigger}"
suggested_status: ${h.status || '-'}
first_status: ${h.first || '-'}
repeat_status: ${h.again || '-'}
repeat_logic: ${h.repeat || '-'}
active: ${h.active || '-'}
source: ${h.source || '-'}
approved: ${h.approved || '-'}
intent: ${h.intent || '-'}
when: ${h.when || '-'}
when_not: ${h.whenNot || '-'}`
  );
}

function reply(text) {
  if (!Array.isArray(sd.chatHistory)) sd.chatHistory = [];
  sd.chatHistory.push({ role: 'user', content: userText });
  sd.chatHistory.push({ role: 'assistant', content: String(text).slice(0, 800) });
  if (sd.chatHistory.length > 12) sd.chatHistory = sd.chatHistory.slice(-12);
  return [{ json: { chat_id: chatId, branch: 'reply', reply_text: String(text).slice(0, 3500) } }];
}

// CONFIRM
if (isConfirm) {
  const prop = sd.pendingProposal;
  if (!prop) return reply('No pending draft. Ask to change a SHEET rule first, then CONFIRM.');
  return [{ json: {
    chat_id: chatId, branch: 'confirm',
    account_no: prop.id || 'sheet_rule_draft', old_status: '',
    new_status: prop.expected_status || '', validation_result: 'Sheet Rule Draft',
    decision_source: 'rules_brain_sheet', matched_keyword: prop.id || '',
    confidence: 'Human', reason: String(prop.summary || '').slice(0, 500),
    example_comment: String(prop.example || '').slice(0, 280), type: 'sheet_rule_draft',
    reply_text: `Sheet rule draft saved.\n\n${String(prop.summary || '').slice(0, 1200)}`
  }}];
}

const low = userText.toLowerCase().trim();

// HELP / MENU for sheet browsing
if (/^(help|yardim|yardım|komut|commands|menu)$/i.test(low)) {
  return reply(
`Google Sheet kural gezgini — yorum şart değil.

• liste — gruplara göre özet
• grup no_answer — o gruptaki kurallar
• sayfa 1 — tüm aktif kurallar (20’şer)
• satir 65 — tek satır detay
• ara no money — trigger ara
• yorum yapıştır — hangi satırlar eşleşir
• exit — çık`
  );
}

// LIST groups summary
if (/^(liste|list|sheet|kurallar|özet|ozet)$/i.test(low)) {
  const byGroup = {};
  for (const h of activeMeta) byGroup[h.group] = (byGroup[h.group] || 0) + 1;
  const lines = Object.entries(byGroup).sort((a,b)=>b[1]-a[1])
    .map(([g,c], i) => `${i+1}. ${g}: ${c}`);
  return reply(
`Google Sheet (CRM_AI_Rules)\nActive: ${activeMeta.length} / total ${allMeta.length}\n\n` +
lines.join('\n') +
`\n\nSonraki: grup <ad>   örn: grup no_answer\nveya: sayfa 1`
  );
}

// GROUP listing: "grup no_answer" / "group rejection" / "liste no_answer"
let grup = userText.match(/^(grup|group|liste|list)\s+([A-Za-z0-9_\- ]+)$/i);
if (grup) {
  const gq = fold(grup[2]);
  if (!['liste','list','sheet','kurallar','ozet','özet'].includes(gq)) {
    const hits = activeMeta.filter(h => fold(h.group) === gq || fold(h.group).includes(gq));
    if (!hits.length) {
      const groups = [...new Set(activeMeta.map(h => h.group))].sort();
      return reply(`Grup bulunamadı: "${grup[2]}"\n\nGruplar:\n` + groups.map(g=>`• ${g}`).join('\n'));
    }
    const top = hits.slice(0, 20);
    return reply(
`Grup "${hits[0].group}" — ${hits.length} kural (showing ${top.length}):\n\n` +
top.map(formatHit).join('\n\n') +
(hits.length > 20 ? `\n\n… +${hits.length-20} more. Use: ara <kelime>` : '')
    );
  }
}

// PAGE browse all active: "sayfa 1" / "page 2" / "hepsi"
let page = 1;
const pageMatch = userText.match(/^(sayfa|page|hepsi|all)\s*(\d+)?$/i);
if (pageMatch) {
  page = Math.max(1, parseInt(pageMatch[2] || '1', 10) || 1);
  const PAGE = 15;
  const start = (page - 1) * PAGE;
  const slice = activeMeta.slice(start, start + PAGE);
  const totalPages = Math.max(1, Math.ceil(activeMeta.length / PAGE));
  if (!slice.length) return reply(`Sayfa ${page} boş. Toplam sayfa: ${totalPages}`);
  return reply(
`Sheet aktif kurallar — sayfa ${page}/${totalPages} (${activeMeta.length} total)\n\n` +
slice.map(formatHit).join('\n\n') +
`\n\nNext: sayfa ${Math.min(totalPages, page+1)}`
  );
}

// ROW detail: "satir 65" / "row 65" / "satır 65"
const rowMatch = userText.match(/^(satir|satır|row|#)\s*(\d+)$/i);
if (rowMatch) {
  const want = String(parseInt(rowMatch[2], 10));
  const hit = allMeta.find(h => String(h.row) === want) ||
    allMeta.find(h => String(h.row) === rowMatch[2]);
  // also allow index if row_number missing: treat as 1-based among sheetRows
  const byIndex = !hit && sheetRows[parseInt(rowMatch[2],10) - 1]
    ? rowMeta(sheetRows[parseInt(rowMatch[2],10) - 1], parseInt(rowMatch[2],10) - 1)
    : null;
  const h = hit || byIndex;
  if (!h) return reply(`Row ${want} bulunamadı. Toplam satır: ${allMeta.length}`);
  return reply(formatDetail(h));
}

// SEARCH
const ara = userText.match(/^(ara|search|bul)\s+(.+)$/i);
if (ara) {
  const q = fold(ara[2]);
  const hits = activeMeta.filter(h =>
    fold(h.trigger).includes(q) || fold(h.status).includes(q) || fold(h.group).includes(q) || fold(h.intent).includes(q)
  );
  hits.sort((a,b) => fold(a.trigger).length - fold(b.trigger).length);
  const top = hits.slice(0, 15);
  return reply(
    top.length
      ? `Ara "${ara[2]}" → ${hits.length} hit, showing ${top.length}:\n\n` + top.map(formatHit).join('\n\n')
      : `Sheet’te "${ara[2]}" yok. Active: ${activeMeta.length}`
  );
}

// MATCH comment against triggers
const normUser = fold(userText);
const matches = [];
for (const h of activeMeta) {
  const t = fold(h.trigger);
  if (t.length < 2) continue;
  if (normUser.includes(t)) matches.push({ ...h, triggerLen: t.length });
}
matches.sort((a,b) => b.triggerLen - a.triggerLen || String(a.row).localeCompare(String(b.row)));
const topMatches = matches.slice(0, 12);

const looksLikeCheck = topMatches.length > 0 || (
  userText.length >= 3 &&
  !/\?$/.test(userText) &&
  !/^(why|neden|nasil|nasıl|what if|degistir|değiştir|change|propose|grup|group|sayfa|page|ara|help)/i.test(userText)
);

if (looksLikeCheck && (topMatches.length > 0 || userText.length < 220)) {
  if (!topMatches.length) {
    return reply(
`Google Sheet: eşleşen trigger yok.\n"${userText}"\nTaranan aktif kural: ${activeMeta.length}\n\n` +
`Sheet gezmek için: liste | sayfa 1 | grup no_answer | ara <kelime>`
    );
  }
  const best = topMatches[0];
  return reply(
`Sheet eşleşmesi:\n"${userText}"\n\n` +
`En iyi → row ${best.row}: "${best.trigger}" → ${best.status || '?'}` +
(best.group ? ` [${best.group}]` : '') + `\n\n` +
`Hits (${matches.length}, showing ${topMatches.length}):\n\n` +
topMatches.map(formatHit).join('\n\n')
  );
}

// AI for open Q / edits — sheet first
const sheetDigest = activeMeta.slice(0, 120).map(h => `row ${h.row}|${h.group}|"${h.trigger}"→${h.status}`).join('\n');
const matchDigest = topMatches.length
  ? topMatches.map(h => `row ${h.row} "${h.trigger}" → ${h.status}`).join('\n')
  : '(no substring match)';

const BRAIN = `You help browse/edit GOOGLE SHEET CRM rules (Sheet1). User language. Concise.
Prefer sheet row numbers and triggers. Canonical policies only as footnotes.
If drafting a sheet change, end with: Reply CONFIRM to save this draft.

SHEET ACTIVE:
${sheetDigest || '(empty)'}

MATCHES:
${matchDigest}`;

if (!Array.isArray(sd.chatHistory)) sd.chatHistory = [];
sd.chatHistory.push({ role: 'user', content: userText });
if (sd.chatHistory.length > 12) sd.chatHistory = sd.chatHistory.slice(-12);
const hist = sd.chatHistory.map(h => `${h.role}: ${h.content}`).join('\n');

return [{ json: {
  chat_id: chatId, branch: 'ai', system_prompt: BRAIN,
  user_message: `Chat:\n${hist}\n\nLatest:\n${userText}`, raw_user: userText
}}];

const sd = $getWorkflowStaticData('global');
const j = $input.first().json;
sd.pendingProposal = null;
return [{ json: j }];

const sd = $getWorkflowStaticData('global');
const prep = $('Prepare Brain').item.json;
const raw = $input.first().json;
let text = '';
try {
  text = raw.choices?.[0]?.message?.content || raw.message?.content || raw.error?.message || JSON.stringify(raw).slice(0, 500);
} catch (e) { text = 'Brain error: could not parse model response.'; }
text = String(text || '').trim() || '(empty reply)';
if (/reply confirm to save/i.test(text)) {
  sd.pendingProposal = {
    id: 'draft_' + Date.now(),
    summary: text.slice(0, 900),
    expected_status: (text.match(/Expected status:\s*(.+)/i) || [,''])[1].trim().slice(0, 80),
    example: (text.match(/Example[^\n]*:\s*(.+)/i) || [,''])[1].trim().slice(0, 200)
  };
}
if (!Array.isArray(sd.chatHistory)) sd.chatHistory = [];
sd.chatHistory.push({ role: 'assistant', content: text.slice(0, 1000) });
if (sd.chatHistory.length > 12) sd.chatHistory = sd.chatHistory.slice(-12);
if (text.length > 3500) text = text.slice(0, 3500) + '\n…';
return [{ json: { chat_id: prep.chat_id, reply_text: text } }];
